-- Boreas Power Personnel Planner import (migration from spreadsheet)
-- Run in Supabase SQL editor

DO $$
DECLARE
  co_id uuid;
  emp_id uuid;
BEGIN
  SELECT id INTO co_id FROM public.companies WHERE slug = 'boreaspower';
  IF co_id IS NULL THEN RAISE EXCEPTION 'boreaspower company not found'; END IF;

  -- Get Fraser McKenzie person_id (Employee row maps to this person)
  SELECT id INTO emp_id FROM public.people
    WHERE company_id = co_id AND name ILIKE '%Fraser%McKenzie%'
    LIMIT 1;

  -- Insert assignments
  ON CONFLICT (person_id, date) WHERE person_id IS NOT NULL DO UPDATE SET
    type = EXCLUDED.type,
    client = EXCLUDED.client,
    scope = EXCLUDED.scope,
    location = EXCLUDED.location,
    updated_at = now();

  RAISE NOTICE 'Planner import complete: % rows upserted', 270;
END $$;